from pathlib import Path
import datetime,json,hashlib,numpy as np
H=Path(__file__).resolve().parent
def load(p):return json.loads(p.read_text(encoding='utf-8-sig'))
def main():
    runs=list(H.glob('run-*'));assert len(runs)==1;run=runs[0];fixture=load(H/'FIXTURE115.json');states=sorted(run.glob('STATE-*.json'));last=load(states[-1])
    assert np.all(np.frombuffer((run/'init-state.bin').read_bytes(),dtype='<u4')==0)
    assert(run/'init-primary.bin').read_bytes()==(H/'best.bin').read_bytes()
    assert last['GPUDispatches']==2 and last['pendingReadbacks']==2 and last['stage']=='pending-no-retry-no-force-disposal'
    assert not(run/'COMPLETE_BOUND115.json').exists()and not(run/'metric-metrics.bin').exists()
    reply=load(H/'BoundRun115_REPLY.json');message=reply.get('error','');compile=load(H/'BoundCompile115b_REPLY.json')['data'];assert compile['isCompilationSuccessful']and compile['isExecutionSuccessful']
    out={'schema':'bounded-sourceform115/result/v1','observedUTC':datetime.datetime.now(datetime.timezone.utc).isoformat(),'run':run.name,'sourceId':fixture['sourceId'],'originalFeatureOwnerId':2,'logicalSlotPermutation':[2,1],'externalFullCompilationPassed':True,'toolRunReportedWarningError':reply.get('success')is False,'toolRunWasNotDenied':True,'partialExecutionProvedByFiles':True,'GPUDispatchesSubmitted':2,'initThreadsCompletedAndValidated':2,'initialStateZeroedByGPU':True,'primaryBestByteCopyExact':True,'metricThreadsSubmitted':2,'metricReadbacksPending':2,'metricGPUCompletionOrParityProved':False,'ParetoDispatchesSubmitted':0,'metricMaxActiveKeys':10,'metricPointLoopBoundPerActiveKey':9,'metricKeyPairTermsPerCandidateUpperBound':21,'ownedGraphicsBufferBytesRetained':last['ownedBufferBytes'],'ownedGraphicsBufferCount':12,'ownedShaderCloneRetained':True,'forceDisposalAttempted':False,'postStatePreservationProved':False,'observedGPUTime':None,'newDeviceResetProved':False,'warningForForcedArrayUnroll':('array reference cannot be used as an l-value'in message and 'forcing loop to unroll'in message),'warningMayNotBeCause':True,'before':{'PID':6288,'dirty':len(load(run/'BEFORE.json')['dirty']),'inputId':load(run/'BEFORE.json')['inputId']},'scopeExclusions':{'Play':0,'BVH':0,'enumeration':0,'rendererOrCamera':0,'newAssetsOrProjectCSharp':0,'globalSetter':0,'InputSettingsReplacement':0,'forceKillResetDriverTDRChanges':0},'lifecycle':'Original observer remains registered while awaiting two callbacks. On error/mismatch no next dispatch; on a late valid completion only the approved1thread Pareto may follow. No retry or forced cleanup was attempted.','causeNarrowing':'Completion stall occurs after2thread Evaluate submission without BVH/exhaustive search/full renderer. It is not explained solely by the large full115 workload. Kernel code/binding/compiler-driver/async completion are not yet separated.','nextBoundary':'Resolve the existing pending operation first. Do not submit a new variant, higher-cost stage, or replay this command. Future diagnostics need an echo-only ABI check, retained request status/public stop-next control, and no dynamically indexed private array/unroll path before larger phases.'}
    with(H/'RESULT_BOUND115.json').open('x',encoding='utf-8')as f:json.dump(out,f,ensure_ascii=False,indent=2)
    print(json.dumps(out,ensure_ascii=False))
if __name__=='__main__':main()
